fn find_similar(name: &str, options: &[&str]) -> Option<String> {
    // Strip leading dashes
    let stripped = name.trim_start_matches('-');
    let mut best: Option<(usize, &str)> = None;
    for opt in options {
        let opt_stripped = opt.trim_start_matches('-');
        let d = edit_distance(stripped, opt_stripped);
        // clap uses 3 as default threshold, with prefix as special case
        let threshold = 3usize;
        if d <= threshold {
            match best {
                None => best = Some((d, opt)),
                Some((cur, _)) if d < cur => best = Some((d, opt)),
                _ => {}
            }
        }
    }
    best.map(|(_, s)| s.to_string())
}

fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let m = a.len();
    let n = b.len();
    if m == 0 {
        return n;
    }
    if n == 0 {
        return m;
    }
    let mut prev: Vec<usize> = (0..=n).collect();
    let mut cur: Vec<usize> = vec![0; n + 1];
    for i in 1..=m {
        cur[0] = i;
        for j in 1..=n {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[n]
}

pub fn parse(args: &[String]) -> ParseResult {
    let bin = if args.is_empty() {
        "executable".to_string()
    } else {
        bin_name(&args[0])
    };

    let known_longs: &[&str] = &["--help", "--version"];

    let mut iter = args.iter().skip(1);
    let mut positional: Option<String> = None;
    let mut extra_positional: Option<String> = None;
    let mut seen_dd = false;

    while let Some(a) = iter.next() {
        if seen_dd {
            if positional.is_none() {
                positional = Some(a.clone());
            } else if extra_positional.is_none() {
                extra_positional = Some(a.clone());
            }
            continue;
        }
        if a == "--" {
            seen_dd = true;
            continue;
        }
        if a.starts_with("--") {
            // Long flag
            let (name, eq_val) = match a.find('=') {
                Some(i) => (&a[..i], Some(&a[i + 1..])),
                None => (a.as_str(), None),
            };
            match name {
                "--help" => {
                    if let Some(v) = eq_val {
                        return ParseResult::Error(unexpected_value("--help", v));
                    }
                    return ParseResult::Help(help_text());
                }
                "--version" => {
                    if let Some(v) = eq_val {
                        return ParseResult::Error(unexpected_value("--version", v));
                    }
                    return ParseResult::Version(version_text());
                }
                _ => {
                    let similar = find_similar(name, known_longs);
                    return ParseResult::Error(unexpected_flag(name, similar.as_deref()));
                }
            }
        } else if a.starts_with('-') && a.len() > 1 && a != "-" {
            // Short flag(s) - allow combined short flags
            let body = &a[1..];
            // Process each short char
            let mut saw_help = false;
            let mut saw_version = false;
            for c in body.chars() {
                match c {
                    'h' => saw_help = true,
                    'V' => saw_version = true,
                    _ => {
                        // Unknown short flag
                        let flag = format!("-{}", c);
                        return ParseResult::Error(unexpected_flag(&flag, None));
                    }
                }
            }
            // Preference: help wins if present, else version
            if saw_help {
                return ParseResult::Help(help_text());
            }
            if saw_version {
                return ParseResult::Version(version_text());
            }
        } else {
            // Positional
            if positional.is_none() {
                positional = Some(a.clone());
            } else if extra_positional.is_none() {
                extra_positional = Some(a.clone());
            }
        }
    }

    if let Some(extra) = extra_positional {
        return ParseResult::Error(unexpected_positional(&extra));
    }

    match positional {
        Some(p) => ParseResult::Run(p),
        None => ParseResult::Error(missing_path_error(&bin)),
    }
}
