// Minimal parquet file loader. Produces errors matching the original tool
// and parses just enough of the metadata footer for our TUI.

use std::fs::{File, metadata};
use std::io::{self, Read, Seek, SeekFrom};

#[derive(Debug, Default, Clone)]
pub struct ParquetFile {
    pub size: u64,
    pub metadata: FileMetadata,
}

#[derive(Debug, Default, Clone)]
pub struct FileMetadata {
    pub version: i32,
    pub created_by: Option<String>,
    pub num_rows: i64,
    pub schema: Vec<SchemaElement>,
    pub row_groups: Vec<RowGroup>,
    pub key_value_metadata: Vec<(String, Option<String>)>,
}

#[derive(Debug, Default, Clone)]
pub struct SchemaElement {
    pub name: String,
    pub type_: Option<i32>,       // PhysicalType
    pub type_length: Option<i32>,
    pub repetition_type: Option<i32>,
    pub num_children: Option<i32>,
    pub converted_type: Option<i32>,
    pub logical_type_name: Option<String>,
}

#[derive(Debug, Default, Clone)]
pub struct RowGroup {
    pub columns: Vec<ColumnChunk>,
    pub total_byte_size: i64,
    pub num_rows: i64,
    pub total_compressed_size: Option<i64>,
}

#[derive(Debug, Default, Clone)]
pub struct ColumnChunk {
    pub file_path: Option<String>,
    pub meta_data: Option<ColumnMetaData>,
}

#[derive(Debug, Default, Clone)]
pub struct ColumnMetaData {
    pub type_: i32,
    pub encodings: Vec<i32>,
    pub path_in_schema: Vec<String>,
    pub codec: i32,
    pub num_values: i64,
    pub total_uncompressed_size: i64,
    pub total_compressed_size: i64,
}

fn other<S: Into<String>>(s: S) -> io::Error {
    io::Error::new(io::ErrorKind::Other, s.into())
}

pub fn load(path: &str) -> io::Result<ParquetFile> {
    // Check stat first (distinguish between "no such file" and "is a directory")
    let md = match metadata(path) {
        Ok(m) => m,
        Err(e) if e.kind() == io::ErrorKind::NotFound => {
            return Err(e); // passthrough "No such file or directory (os error 2)"
        }
        Err(e) => return Err(e),
    };
    if md.is_dir() {
        // Match "External: Is a directory (os error 21)" exactly
        let e = io::Error::from_raw_os_error(21);
        return Err(other(format!("External: {}", e)));
    }

    let mut file = match File::open(path) {
        Ok(f) => f,
        Err(e) if e.kind() == io::ErrorKind::NotFound => return Err(e),
        Err(e) => return Err(e),
    };
    let size = md.len();
    if size < 8 {
        return Err(other(format!(
            "EOF: Parquet file too small. Size is {} but need 8",
            size
        )));
    }

    // Read last 8 bytes
    file.seek(SeekFrom::End(-8))?;
    let mut footer = [0u8; 8];
    file.read_exact(&mut footer)?;
    if &footer[4..] != b"PAR1" {
        return Err(other(
            "Parquet error: Invalid Parquet file. Corrupt footer".to_string(),
        ));
    }
    let metadata_len = u32::from_le_bytes([footer[0], footer[1], footer[2], footer[3]]) as u64;
    let required = metadata_len + 8;
    if required > size {
        return Err(other(format!(
            "EOF: Parquet file too small. Size is {} but need {}",
            size, required
        )));
    }
    // Read metadata bytes
    let mut buf = vec![0u8; metadata_len as usize];
    file.seek(SeekFrom::End(-(8 + metadata_len as i64)))?;
    file.read_exact(&mut buf)?;

    // Parse thrift compact
    let md = parse_file_metadata(&buf).map_err(|e| other(e))?;
    Ok(ParquetFile { size, metadata: md })
}

// ---------- Thrift Compact Protocol decoder ----------

struct TcReader<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> TcReader<'a> {
    fn new(data: &'a [u8]) -> Self {
        Self { data, pos: 0 }
    }
    fn remaining(&self) -> usize {
        self.data.len() - self.pos
    }
    fn need(&self, n: usize) -> Result<(), String> {
        if self.remaining() < n {
            Err("Parquet error: Could not parse metadata: end of file".into())
        } else {
            Ok(())
        }
    }
    fn read_byte(&mut self) -> Result<u8, String> {
        self.need(1)?;
        let b = self.data[self.pos];
        self.pos += 1;
        Ok(b)
    }
    fn read_varint_u64(&mut self) -> Result<u64, String> {
        let mut result: u64 = 0;
        let mut shift = 0u32;
        loop {
            let b = self.read_byte()?;
            result |= ((b & 0x7F) as u64) << shift;
            if (b & 0x80) == 0 {
                break;
            }
            shift += 7;
            if shift > 63 {
                return Err("Parquet error: Could not parse metadata: protocol error".into());
            }
        }
        Ok(result)
    }
    fn read_varint_i32(&mut self) -> Result<i32, String> {
        let u = self.read_varint_u64()? as u32;
        Ok(((u >> 1) as i32) ^ -((u & 1) as i32))
    }
    fn read_varint_i64(&mut self) -> Result<i64, String> {
        let u = self.read_varint_u64()?;
        Ok(((u >> 1) as i64) ^ -((u & 1) as i64))
    }
    fn read_binary(&mut self) -> Result<Vec<u8>, String> {
        let len = self.read_varint_u64()? as usize;
        if self.remaining() < len {
            return Err("Parquet error: Could not parse metadata: end of file".into());
        }
        let v = self.data[self.pos..self.pos + len].to_vec();
        self.pos += len;
        Ok(v)
    }
    fn read_double(&mut self) -> Result<f64, String> {
        if self.remaining() < 8 {
            return Err("Parquet error: Could not parse metadata: end of file".into());
        }
        let mut bs = [0u8; 8];
        bs.copy_from_slice(&self.data[self.pos..self.pos + 8]);
        self.pos += 8;
        Ok(f64::from_le_bytes(bs))
    }

    fn read_field_header(&mut self, last_id: &mut i16) -> Result<Option<(u8, i16)>, String> {
        let b = self.read_byte()?;
        if b == 0 {
            return Ok(None); // STOP
        }
        let ttype = b & 0x0F;
        let delta = (b >> 4) & 0x0F;
        let fid = if delta != 0 {
            *last_id + delta as i16
        } else {
            // full ZigZag i16
            let u = self.read_varint_u64()? as u32;
            ((u >> 1) as i16) ^ -((u & 1) as i16)
        };
        *last_id = fid;
        Ok(Some((ttype, fid)))
    }
    fn read_list_header(&mut self) -> Result<(u8, usize), String> {
        let b = self.read_byte()?;
        let ttype = b & 0x0F;
        let size = (b >> 4) & 0x0F;
        let size = if size == 0x0F {
            self.read_varint_u64()? as usize
        } else {
            size as usize
        };
        Ok((ttype, size))
    }
    fn skip(&mut self, ttype: u8) -> Result<(), String> {
        match ttype {
            1 | 2 => { /* bool true/false: no data */ }
            3 => {
                self.read_byte()?;
            }
            4 | 5 | 6 => {
                self.read_varint_u64()?;
            }
            7 => {
                self.read_double()?;
            }
            8 => {
                let _ = self.read_binary()?;
            }
            9 | 10 => {
                // list / set
                let (it, sz) = self.read_list_header()?;
                for _ in 0..sz {
                    self.skip(it)?;
                }
            }
            11 => {
                // map
                let sz = self.read_varint_u64()? as usize;
                if sz > 0 {
                    let kv = self.read_byte()?;
                    let kt = (kv >> 4) & 0x0F;
                    let vt = kv & 0x0F;
                    for _ in 0..sz {
                        self.skip(kt)?;
                        self.skip(vt)?;
                    }
                }
            }
            12 => {
                // struct
                let mut last = 0i16;
                loop {
                    match self.read_field_header(&mut last)? {
                        None => break,
                        Some((t, _)) => self.skip(t)?,
                    }
                }
            }
            _ => return Err("Parquet error: Could not parse metadata: protocol error".into()),
        }
        Ok(())
    }
}

// Thrift compact type codes
const TT_STOP: u8 = 0;
const TT_TRUE: u8 = 1;
const TT_FALSE: u8 = 2;
const TT_I8: u8 = 3;
const TT_I16: u8 = 4;
const TT_I32: u8 = 5;
const TT_I64: u8 = 6;
const TT_DOUBLE: u8 = 7;
const TT_BINARY: u8 = 8;
const TT_LIST: u8 = 9;
const TT_SET: u8 = 10;
const TT_MAP: u8 = 11;
const TT_STRUCT: u8 = 12;

fn parse_file_metadata(buf: &[u8]) -> Result<FileMetadata, String> {
    let mut r = TcReader::new(buf);
    let mut md = FileMetadata::default();
    let mut last_id = 0i16;
    loop {
        match r.read_field_header(&mut last_id)? {
            None => break,
            Some((t, id)) => match id {
                1 => {
                    if t != TT_I32 {
                        r.skip(t)?;
                    } else {
                        md.version = r.read_varint_i32()?;
                    }
                }
                2 => {
                    if t != TT_LIST {
                        r.skip(t)?;
                    } else {
                        let (it, sz) = r.read_list_header()?;
                        if it != TT_STRUCT {
                            for _ in 0..sz {
                                r.skip(it)?;
                            }
                        } else {
                            for _ in 0..sz {
                                md.schema.push(parse_schema_element(&mut r)?);
                            }
                        }
                    }
                }
                3 => {
                    if t != TT_I64 {
                        r.skip(t)?;
                    } else {
                        md.num_rows = r.read_varint_i64()?;
                    }
                }
                4 => {
                    if t != TT_LIST {
                        r.skip(t)?;
                    } else {
                        let (it, sz) = r.read_list_header()?;
                        if it != TT_STRUCT {
                            for _ in 0..sz {
                                r.skip(it)?;
                            }
                        } else {
                            for _ in 0..sz {
                                md.row_groups.push(parse_row_group(&mut r)?);
                            }
                        }
                    }
                }
                5 => {
                    if t != TT_LIST {
                        r.skip(t)?;
                    } else {
                        let (it, sz) = r.read_list_header()?;
                        if it != TT_STRUCT {
                            for _ in 0..sz {
                                r.skip(it)?;
                            }
                        } else {
                            for _ in 0..sz {
                                md.key_value_metadata.push(parse_kv(&mut r)?);
                            }
                        }
                    }
                }
                6 => {
                    if t != TT_BINARY {
                        r.skip(t)?;
                    } else {
                        let b = r.read_binary()?;
                        md.created_by = Some(String::from_utf8_lossy(&b).into_owned());
                    }
                }
                _ => r.skip(t)?,
            },
        }
    }
    Ok(md)
}

fn parse_schema_element(r: &mut TcReader) -> Result<SchemaElement, String> {
    let mut el = SchemaElement::default();
    let mut last_id = 0i16;
    loop {
        match r.read_field_header(&mut last_id)? {
            None => break,
            Some((t, id)) => match id {
                1 => {
                    if t == TT_I32 {
                        el.type_ = Some(r.read_varint_i32()?);
                    } else {
                        r.skip(t)?;
                    }
                }
                2 => {
                    if t == TT_I32 {
                        el.type_length = Some(r.read_varint_i32()?);
                    } else {
                        r.skip(t)?;
                    }
                }
                3 => {
                    if t == TT_I32 {
                        el.repetition_type = Some(r.read_varint_i32()?);
                    } else {
                        r.skip(t)?;
                    }
                }
                4 => {
                    if t == TT_BINARY {
                        let b = r.read_binary()?;
                        el.name = String::from_utf8_lossy(&b).into_owned();
                    } else {
                        r.skip(t)?;
                    }
                }
                5 => {
                    if t == TT_I32 {
                        el.num_children = Some(r.read_varint_i32()?);
                    } else {
                        r.skip(t)?;
                    }
                }
                6 => {
                    if t == TT_I32 {
                        el.converted_type = Some(r.read_varint_i32()?);
                    } else {
                        r.skip(t)?;
                    }
                }
                _ => r.skip(t)?,
            },
        }
    }
    Ok(el)
}

fn parse_row_group(r: &mut TcReader) -> Result<RowGroup, String> {
    let mut rg = RowGroup::default();
    let mut last_id = 0i16;
    loop {
        match r.read_field_header(&mut last_id)? {
            None => break,
            Some((t, id)) => match id {
                1 => {
                    if t == TT_LIST {
                        let (it, sz) = r.read_list_header()?;
                        if it != TT_STRUCT {
                            for _ in 0..sz {
                                r.skip(it)?;
                            }
                        } else {
                            for _ in 0..sz {
                                rg.columns.push(parse_column_chunk(r)?);
                            }
                        }
                    } else {
                        r.skip(t)?;
                    }
                }
                2 => {
                    if t == TT_I64 {
                        rg.total_byte_size = r.read_varint_i64()?;
                    } else {
                        r.skip(t)?;
                    }
                }
                3 => {
                    if t == TT_I64 {
                        rg.num_rows = r.read_varint_i64()?;
                    } else {
                        r.skip(t)?;
                    }
                }
                6 => {
                    if t == TT_I64 {
                        rg.total_compressed_size = Some(r.read_varint_i64()?);
                    } else {
                        r.skip(t)?;
                    }
                }
                _ => r.skip(t)?,
            },
        }
    }
    Ok(rg)
}

fn parse_column_chunk(r: &mut TcReader) -> Result<ColumnChunk, String> {
    let mut cc = ColumnChunk::default();
    let mut last_id = 0i16;
    loop {
        match r.read_field_header(&mut last_id)? {
            None => break,
            Some((t, id)) => match id {
                1 => {
                    if t == TT_BINARY {
                        let b = r.read_binary()?;
                        cc.file_path = Some(String::from_utf8_lossy(&b).into_owned());
                    } else {
                        r.skip(t)?;
                    }
                }
                3 => {
                    if t == TT_STRUCT {
                        cc.meta_data = Some(parse_column_metadata(r)?);
                    } else {
                        r.skip(t)?;
                    }
                }
                _ => r.skip(t)?,
            },
        }
    }
    Ok(cc)
}

fn parse_column_metadata(r: &mut TcReader) -> Result<ColumnMetaData, String> {
    let mut cm = ColumnMetaData::default();
    let mut last_id = 0i16;
    loop {
        match r.read_field_header(&mut last_id)? {
            None => break,
            Some((t, id)) => match id {
                1 => {
                    if t == TT_I32 {
                        cm.type_ = r.read_varint_i32()?;
                    } else {
                        r.skip(t)?;
                    }
                }
                2 => {
                    if t == TT_LIST {
                        let (it, sz) = r.read_list_header()?;
                        for _ in 0..sz {
                            if it == TT_I32 {
                                cm.encodings.push(r.read_varint_i32()?);
                            } else {
                                r.skip(it)?;
                            }
                        }
                    } else {
                        r.skip(t)?;
                    }
                }
                3 => {
                    if t == TT_LIST {
                        let (it, sz) = r.read_list_header()?;
                        for _ in 0..sz {
                            if it == TT_BINARY {
                                let b = r.read_binary()?;
                                cm.path_in_schema
                                    .push(String::from_utf8_lossy(&b).into_owned());
                            } else {
                                r.skip(it)?;
                            }
                        }
                    } else {
                        r.skip(t)?;
                    }
                }
                4 => {
                    if t == TT_I32 {
                        cm.codec = r.read_varint_i32()?;
                    } else {
                        r.skip(t)?;
                    }
                }
                5 => {
                    if t == TT_I64 {
                        cm.num_values = r.read_varint_i64()?;
                    } else {
                        r.skip(t)?;
                    }
                }
                6 => {
                    if t == TT_I64 {
                        cm.total_uncompressed_size = r.read_varint_i64()?;
                    } else {
                        r.skip(t)?;
                    }
                }
                7 => {
                    if t == TT_I64 {
                        cm.total_compressed_size = r.read_varint_i64()?;
                    } else {
                        r.skip(t)?;
                    }
                }
                _ => r.skip(t)?,
            },
        }
    }
    Ok(cm)
}

fn parse_kv(r: &mut TcReader) -> Result<(String, Option<String>), String> {
    let mut key = String::new();
    let mut value: Option<String> = None;
    let mut last_id = 0i16;
    loop {
        match r.read_field_header(&mut last_id)? {
            None => break,
            Some((t, id)) => match id {
                1 => {
                    if t == TT_BINARY {
                        let b = r.read_binary()?;
                        key = String::from_utf8_lossy(&b).into_owned();
                    } else {
                        r.skip(t)?;
                    }
                }
                2 => {
                    if t == TT_BINARY {
                        let b = r.read_binary()?;
                        value = Some(String::from_utf8_lossy(&b).into_owned());
                    } else {
                        r.skip(t)?;
                    }
                }
                _ => r.skip(t)?,
            },
        }
    }
    Ok((key, value))
}

