// Minimal terminal raw-mode helper using libc via FFI.

use std::io::{self, Read, Write};
use std::mem::MaybeUninit;
use std::os::unix::io::{AsRawFd, RawFd};

pub const STDIN_FD: RawFd = 0;
pub const STDOUT_FD: RawFd = 1;

#[repr(C)]
#[derive(Clone, Copy)]
pub struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

#[repr(C)]
pub struct Winsize {
    pub ws_row: u16,
    pub ws_col: u16,
    pub ws_xpixel: u16,
    pub ws_ypixel: u16,
}

extern "C" {
    fn tcgetattr(fd: i32, t: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, action: i32, t: *const Termios) -> i32;
    fn ioctl(fd: i32, req: u64, ...) -> i32;
    fn isatty(fd: i32) -> i32;
}

const TCSANOW: i32 = 0;
const TIOCGWINSZ: u64 = 0x5413;

// termios flag bits
const IGNBRK: u32 = 0o000001;
const BRKINT: u32 = 0o000002;
const PARMRK: u32 = 0o000010;
const ISTRIP: u32 = 0o000040;
const INLCR: u32 = 0o000100;
const IGNCR: u32 = 0o000200;
const ICRNL: u32 = 0o000400;
const IXON: u32 = 0o002000;

const OPOST: u32 = 0o000001;

const CS8: u32 = 0o000060;

const ECHO: u32 = 0o000010;
const ICANON: u32 = 0o000002;
const ISIG: u32 = 0o000001;
const IEXTEN: u32 = 0o100000;

const VMIN: usize = 6;
const VTIME: usize = 5;

pub struct RawGuard {
    fd: RawFd,
    orig: Termios,
}

impl RawGuard {
    pub fn new() -> io::Result<Self> {
        unsafe {
            let fd = STDIN_FD;
            if isatty(fd) == 0 {
                // Match ratatui's panic shape a bit. Return an error.
                return Err(io::Error::from_raw_os_error(6));
            }
            let mut t: MaybeUninit<Termios> = MaybeUninit::uninit();
            if tcgetattr(fd, t.as_mut_ptr()) != 0 {
                return Err(io::Error::last_os_error());
            }
            let orig = t.assume_init();
            let mut raw = orig;
            raw.c_iflag &= !(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
            raw.c_oflag &= !OPOST;
            raw.c_lflag &= !(ECHO | ICANON | ISIG | IEXTEN);
            raw.c_cflag |= CS8;
            raw.c_cc[VMIN] = 0;
            raw.c_cc[VTIME] = 1; // 100ms poll
            if tcsetattr(fd, TCSANOW, &raw) != 0 {
                return Err(io::Error::last_os_error());
            }
            Ok(Self { fd, orig })
        }
    }
}

impl Drop for RawGuard {
    fn drop(&mut self) {
        unsafe {
            tcsetattr(self.fd, TCSANOW, &self.orig);
        }
    }
}

pub fn winsize() -> (u16, u16) {
    unsafe {
        let mut ws: MaybeUninit<Winsize> = MaybeUninit::uninit();
        if ioctl(STDOUT_FD, TIOCGWINSZ, ws.as_mut_ptr()) == 0 {
            let w = ws.assume_init();
            (w.ws_col.max(20), w.ws_row.max(5))
        } else {
            (80, 24)
        }
