// Minimal TUI renderer for parqeye.

use std::io::{self, Read, Write};
use crate::parquet::{ParquetFile, FileMetadata, physical_type_name, repetition_name, codec_name, encoding_name};
use crate::term::{self, RawGuard, Key};

#[derive(Clone, Copy, PartialEq, Eq)]
enum Tab {
    Visualize,
    Metadata,
    Schema,
    RowGroups,
}

impl Tab {
    fn next(self) -> Tab {
        match self {
            Tab::Visualize => Tab::Metadata,
            Tab::Metadata => Tab::Schema,
            Tab::Schema => Tab::RowGroups,
            Tab::RowGroups => Tab::Visualize,
        }
    }
}

struct App<'a> {
    path: &'a str,
    file: &'a ParquetFile,
    tab: Tab,
}

pub fn run(path: &str, file: &ParquetFile) -> io::Result<()> {
    let _raw = RawGuard::new().map_err(|e| {
        // Match original panic shape roughly.
        eprintln!("\x1b[?1049l");
        eprintln!(
            "thread 'main' panicked: failed to initialize terminal: {:?}",
            e
        );
        e
    })?;
    let mut stdout = io::stdout().lock();
    term::enter_alt_screen(&mut stdout)?;

    let mut app = App {
        path,
        file,
        tab: Tab::Visualize,
    };

    let res = event_loop(&mut app, &mut stdout);
    term::leave_alt_screen(&mut stdout)?;
    res
}

fn event_loop<W: Write>(app: &mut App, out: &mut W) -> io::Result<()> {
    let mut stdin = io::stdin();
    draw(app, out)?;
    let mut buf = [0u8; 1];
    loop {
        // Blocking-ish read (VMIN=0, VTIME=1)
        match stdin.read(&mut buf) {
            Ok(0) => continue,
            Ok(_) => {
                let key = match buf[0] {
                    b'q' => return Ok(()),
                    b'\t' => Key::Tab,
                    b'\x1b' => {
                        // try read more for escape sequences
                        let mut nb = [0u8; 1];
                        if let Ok(1) = stdin.read(&mut nb) {
                            if nb[0] == b'[' {
                                let mut seq = Vec::new();
                                loop {
                                    let mut c = [0u8; 1];
                                    let n = stdin.read(&mut c).unwrap_or(0);
                                    if n == 0 { break; }
                                    seq.push(c[0]);
                                    if c[0] >= 0x40 && c[0] <= 0x7E { break; }
                                }
                                match seq.as_slice() {
                                    b"A" => Key::Up,
                                    b"B" => Key::Down,
                                    b"C" => Key::Right,
                                    b"D" => Key::Left,
                                    _ => Key::Other,
                                }
                            } else { Key::Esc }
                        } else { Key::Esc }
                    }
                    b => Key::Char(b as char),
                };
                match key {
                    Key::Tab => app.tab = app.tab.next(),
                    _ => {}
                }
                draw(app, out)?;
            }
            Err(ref e) if e.kind() == io::ErrorKind::Interrupted => continue,
            Err(_) => continue,
        }
    }
}

fn draw<W: Write>(app: &App, out: &mut W) -> io::Result<()> {
    let (cols, rows) = term::winsize();
    // Clear screen
    write!(out, "\x1b[2J\x1b[H")?;
    // Top tab bar
    draw_tab_bar(app, out, cols)?;
    // Body area
    match app.tab {
        Tab::Visualize => draw_visualize(app, out, cols, rows),
        Tab::Metadata => draw_metadata(app, out, cols, rows),
        Tab::Schema => draw_schema(app, out, cols, rows),
        Tab::RowGroups => draw_row_groups(app, out, cols, rows),
    }?;
    // Status line at the bottom
    draw_status(app, out, cols, rows)?;
    out.flush()
}

fn move_to(out: &mut impl Write, row: u16, col: u16) -> io::Result<()> {
    write!(out, "\x1b[{};{}H", row, col)
}

fn draw_tab_bar<W: Write>(app: &App, out: &mut W, cols: u16) -> io::Result<()> {
    // Three-line rounded border at top
    let width = cols as usize;
    if width < 4 { return Ok(()); }
    // Top line
    move_to(out, 1, 1)?;
    write!(out, "╭")?;
    for _ in 0..width.saturating_sub(2) { write!(out, "─")?; }
    write!(out, "╮")?;
    // Middle line with tab names and file path
    move_to(out, 2, 1)?;
    write!(out, "│ ")?;
    let tabs = [("Visualize", Tab::Visualize), ("Metadata", Tab::Metadata), ("Schema", Tab::Schema), ("Row Groups", Tab::RowGroups)];
    let mut written = 2; // started with "│ "
    for (i, (label, t)) in tabs.iter().enumerate() {
        let is_selected = *t == app.tab;
        if is_selected {
            write!(out, "\x1b[1m{}\x1b[22m", label)?;
        } else {
            write!(out, "{}", label)?;
        }
        written += label.chars().count();
        if i != tabs.len() - 1 {
            write!(out, "   ")?;
            written += 3;
        }
    }
    // Fill with spaces until we have room for path
    let path_chars: Vec<char> = app.path.chars().collect();
    let path_len = path_chars.len();
    // Minimum gap of 2 spaces then path, then `│`
    // inner area is width-2 chars wide; we've written `written` already (excluding outer borders)
    let available = (width - 2) as isize;
    let spaces = available - written as isize - path_len as isize - 1; // -1 for trailing space
    if spaces > 0 {
        for _ in 0..spaces { write!(out, " ")?; }
    }
    // Write path if room
    if path_len as isize <= available - written as isize {
        write!(out, "{}", app.path)?;
    }
    write!(out, "│")?;
    // Bottom line
    move_to(out, 3, 1)?;
    write!(out, "╰")?;
    for _ in 0..width.saturating_sub(2) { write!(out, "─")?; }
    write!(out, "╯")?;
    Ok(())
}

fn draw_visualize<W: Write>(app: &App, out: &mut W, cols: u16, rows: u16) -> io::Result<()> {
    let start_row = 4;
    let end_row = rows.saturating_sub(1);
    // Column headers line
    move_to(out, start_row, 1)?;
    // We show row numbers in a leading column
    let md: &FileMetadata = &app.file.metadata;
    let leaf_columns = collect_leaf_columns(md);
    // compute fixed widths
    let idx_w: usize = 6;
    // We'll estimate remaining width divided among leaf columns
    let avail = cols as usize - idx_w;
    let n = leaf_columns.len().max(1);
    let per = (avail / n).max(6);
    write!(out, "     ")?; // 5 spaces padding for row number column
    for (i, col) in leaf_columns.iter().enumerate() {
        let name = col.as_str();
        let cell = truncate_to_width(name, per.saturating_sub(2));
        write!(out, "  {:<w$}", cell, w = per.saturating_sub(2))?;
        let _ = i;
    }
    // Divider row
    move_to(out, start_row + 1, 1)?;
    for _ in 0..idx_w { write!(out, "─")?; }
    write!(out, "┬")?;
    let tail = cols as usize - idx_w - 1;
    for _ in 0..tail { write!(out, "─")?; }
    // Leave body blank (no actual rows).
    for r in (start_row + 2)..end_row {
        move_to(out, r, 1)?;
        write!(out, "      │")?;
    }
    Ok(())
}

fn draw_metadata<W: Write>(app: &App, out: &mut W, cols: u16, rows: u16) -> io::Result<()> {
    let md = &app.file.metadata;
    let size = app.file.size;

    // Build fields
    let (total_compressed, total_uncompressed) = total_sizes(md);
    let ratio = if total_compressed > 0 {
        total_uncompressed as f64 / total_compressed as f64
    } else {
        1.0
    };
    let codecs = codec_summary(md);
    let encodings = encoding_summary(md);

    let rows_count = md.num_rows;
    let num_cols = collect_leaf_columns(md).len();
    let num_rgs = md.row_groups.len();

    let avg_row_size = if rows_count > 0 {
        total_uncompressed / rows_count.max(1)
    } else {
        0
    };

    let created_by = md
        .created_by
        .clone()
        .unwrap_or_else(|| "<unknown>".to_string());

    let entries: Vec<(&str, String)> = vec![
        ("Format version", format!("{}", md.version)),
        ("Created by", created_by),
        ("Rows", format!("{}", rows_count)),
        ("Columns", format!("{}", num_cols)),
        ("Row groups", format!("{}", num_rgs)),
        ("Size (raw)", format_size(size)),
        ("Size (compressed)", format_size(total_compressed as u64)),
        ("Compression ratio", format!("{:.2}x", ratio)),
        ("Codecs (cols)", codecs),
        ("Encodings", encodings),
        ("Avg row size", format_size(avg_row_size as u64)),
    ];

    let label_w = entries.iter().map(|(k, _)| k.len()).max().unwrap_or(0);
    let value_w = entries.iter().map(|(_, v)| v.len()).max().unwrap_or(0);
    let inner_w = label_w + 1 + value_w + 2; // "label value  "
    let inner_w = inner_w.max(40);
    let box_w = inner_w + 2;
    let box_h = entries.len() + 2;
    let cols_u = cols as usize;
    let rows_u = rows as usize;
    let start_col = (cols_u.saturating_sub(box_w)) / 2 + 1;
    let start_row = (rows_u.saturating_sub(box_h)) / 2 + 1;

    // Title
    let title = "File Metadata";
    let mut top = String::new();
    top.push('╭');
    let side = inner_w.saturating_sub(title.len()) / 2;
    for _ in 0..side { top.push('─'); }
    top.push_str(title);
    let remaining = inner_w - side - title.len();
    for _ in 0..remaining { top.push('─'); }
    top.push('╮');
    move_to(out, start_row as u16, start_col as u16)?;
    write!(out, "{}", top)?;

    for (i, (k, v)) in entries.iter().enumerate() {
        move_to(out, (start_row + 1 + i) as u16, start_col as u16)?;
        write!(
            out,
            "│ {:>kw$} {:<vw$} │",
            k,
            v,
            kw = label_w,
            vw = value_w
        )?;
    }
    move_to(out, (start_row + box_h - 1) as u16, start_col as u16)?;
    write!(out, "╰")?;
    for _ in 0..inner_w { write!(out, "─")?; }
    write!(out, "╯")?;
    Ok(())
}

fn draw_schema<W: Write>(app: &App, out: &mut W, cols: u16, rows: u16) -> io::Result<()> {
    let md = &app.file.metadata;
    let end_row = rows.saturating_sub(1);
    let tree_w: u16 = 26;
    // Left panel top border with title
    move_to(out, 4, 1)?;
    let title = "Schema Tree";
    write!(out, "╭")?;
    let pad = (tree_w as usize - 2).saturating_sub(title.len()) / 2;
    for _ in 0..pad { write!(out, "─")?; }
    write!(out, "{}", title)?;
    let rem = (tree_w as usize - 2) - pad - title.len();
    for _ in 0..rem { write!(out, "─")?; }
    write!(out, "╮")?;
    // Tree lines
    let schema_names = schema_display_lines(md);
    let mut row_i = 5u16;
    for (depth, name) in &schema_names {
        if row_i >= end_row.saturating_sub(1) { break; }
        move_to(out, row_i, 1)?;
        write!(out, "│")?;
        // tree indentation with box drawing
        let prefix = if *depth == 0 {
            "└─ ".to_string()
        } else {
            format!("{}├─ ", "   ".repeat(*depth))
        };
        let line = format!("{}{}", prefix, name);
        let trimmed = truncate_to_width(&line, tree_w as usize - 2);
        write!(out, "{:<w$}", trimmed, w = tree_w as usize - 2)?;
        write!(out, "│")?;
        row_i += 1;
    }
    while row_i < end_row.saturating_sub(1) {
        move_to(out, row_i, 1)?;
        write!(out, "│")?;
        for _ in 0..tree_w-2 { write!(out, " ")?; }
        write!(out, "│")?;
        row_i += 1;
    }
    move_to(out, end_row.saturating_sub(1), 1)?;
    write!(out, "╰")?;
    let footer = "Leaf, Group";
    let pad = (tree_w as usize - 2).saturating_sub(footer.len()) / 2;
    for _ in 0..pad { write!(out, "─")?; }
    write!(out, "{}", footer)?;
    let rem = (tree_w as usize - 2) - pad - footer.len();
    for _ in 0..rem { write!(out, "─")?; }
    write!(out, "╯")?;

    // Right panel
    let right_col = tree_w + 1;
    let right_w = cols.saturating_sub(right_col - 1);
    move_to(out, 4, right_col)?;
    let title = "Column Statistics";
    write!(out, "╭")?;
    let inner = right_w.saturating_sub(2) as usize;
    let pad = inner.saturating_sub(title.len()) / 2;
    for _ in 0..pad { write!(out, "─")?; }
    write!(out, "{}", title)?;
    let rem = inner - pad - title.len();
    for _ in 0..rem { write!(out, "─")?; }
    write!(out, "╮")?;

    // header row
    move_to(out, 5, right_col)?;
    write!(out, "│")?;
    let header = "Repetition  Physical    Compressed  Uncompressed  Ratio  Encodings                     Compression";
    let header = truncate_to_width(header, inner);
    write!(out, "{:<w$}", header, w = inner)?;
    write!(out, "│")?;

    // Per-column rows
    let cols_info = collect_column_rows(md);
    let mut row_i = 6u16;
    for line in cols_info {
        if row_i >= end_row.saturating_sub(1) { break; }
        move_to(out, row_i, right_col)?;
        write!(out, "│")?;
        let trimmed = truncate_to_width(&line, inner);
        write!(out, "{:<w$}", trimmed, w = inner)?;
        write!(out, "│")?;
        row_i += 1;
    }
    while row_i < end_row.saturating_sub(1) {
        move_to(out, row_i, right_col)?;
        write!(out, "│")?;
        for _ in 0..inner { write!(out, " ")?; }
        write!(out, "│")?;
        row_i += 1;
    }
    move_to(out, end_row.saturating_sub(1), right_col)?;
    write!(out, "╰")?;
    for _ in 0..inner { write!(out, "─")?; }
    write!(out, "╯")?;
    Ok(())
}

fn draw_row_groups<W: Write>(app: &App, out: &mut W, cols: u16, rows: u16) -> io::Result<()> {
    let md = &app.file.metadata;
    let n = md.row_groups.len();
    let start_row = 4u16;
    // Header: "Row Group: X / N" inside a small box
    move_to(out, start_row, 1)?;
    write!(out, "┌ Row Group: 1 / {} ", n)?;
    for _ in 0..cols.saturating_sub(20) { write!(out, "─")?; }
    write!(out, "┐")?;
    move_to(out, start_row + 1, 1)?;
    write!(out, "│")?;
    for _ in 0..cols.saturating_sub(2) { write!(out, "█")?; }
    write!(out, "│")?;
    move_to(out, start_row + 2, 1)?;
    write!(out, "└")?;
    for _ in 0..cols.saturating_sub(2) { write!(out, "─")?; }
    write!(out, "┘")?;
    Ok(())
}

fn draw_status<W: Write>(app: &App, out: &mut W, cols: u16, rows: u16) -> io::Result<()> {
    let r = rows;
    move_to(out, r, 1)?;
    let left = "parqeye";
    let right = match app.tab {
        Tab::Visualize => "↑/↓ : Row | →/← : Column | u/d : Page - [Tab] Next Tab, [Q]uit".to_string(),
        Tab::Metadata => "[Tab] Next Tab, [Q]uit".to_string(),
        Tab::Schema => "←/→ : Scroll, ↑/↓ : Schema - [Tab] Next Tab, [Q]uit".to_string(),
        Tab::RowGroups => "←/→ : Row Group, ↑/↓ : Column - [Tab] Next Tab, [Q]uit".to_string(),
    };
    let lw = left.chars().count();
    let rw = right.chars().count();
    let cw = cols as usize;
    let gap = cw.saturating_sub(lw + rw);
    write!(out, "{}", left)?;
    for _ in 0..gap { write!(out, " ")?; }
    write!(out, "{}", right)?;
    Ok(())
}

// --------- Helpers ---------

fn truncate_to_width(s: &str, w: usize) -> String {
    let mut out = String::new();
    let mut n = 0usize;
    for c in s.chars() {
        let cw = 1; // Treat non-wide chars as 1-wide (approx)
        if n + cw > w { break; }
        out.push(c);
        n += cw;
    }
    out
}

fn format_size(bytes: u64) -> String {
    const UNITS: &[&str] = &["B", "KiB", "MiB", "GiB", "TiB", "PiB"];
    if bytes < 1024 {
        return format!("{} B", bytes);
    }
    let mut v = bytes as f64;
    let mut u = 0;
    while v >= 1024.0 && u < UNITS.len() - 1 {
        v /= 1024.0;
        u += 1;
    }
    format!("{:.2} {}", v, UNITS[u])
}

fn collect_leaf_columns(md: &FileMetadata) -> Vec<String> {
    // Scan first row group's ColumnMetaData for path_in_schema last segment
    if let Some(rg) = md.row_groups.first() {
        rg.columns
            .iter()
            .filter_map(|c| c.meta_data.as_ref().and_then(|m| m.path_in_schema.last().cloned()))
            .collect()
    } else {
        // Fallback: schema elements
        md.schema.iter().skip(1).map(|e| e.name.clone()).collect()
    }
}

fn total_sizes(md: &FileMetadata) -> (i64, i64) {
    let mut c = 0i64;
    let mut u = 0i64;
    for rg in &md.row_groups {
        for col in &rg.columns {
            if let Some(m) = &col.meta_data {
                c += m.total_compressed_size;
                u += m.total_uncompressed_size;
            }
        }
    }
    (c, u)
}

fn codec_summary(md: &FileMetadata) -> String {
    use std::collections::BTreeMap;
    let mut counts: BTreeMap<&'static str, i32> = BTreeMap::new();
    for rg in &md.row_groups {
        for c in &rg.columns {
            if let Some(m) = &c.meta_data {
                *counts.entry(codec_name(m.codec)).or_insert(0) += 1;
            }
        }
    }
    counts
        .into_iter()
        .map(|(k, v)| format!("{}({})", k, v))
        .collect::<Vec<_>>()
        .join(", ")
}

fn encoding_summary(md: &FileMetadata) -> String {
    use std::collections::BTreeSet;
    let mut set: BTreeSet<&'static str> = BTreeSet::new();
    for rg in &md.row_groups {
        for c in &rg.columns {
            if let Some(m) = &c.meta_data {
                for e in &m.encodings {
                    set.insert(encoding_name(*e));
                }
            }
        }
    }
    set.into_iter().collect::<Vec<_>>().join(", ")
}

fn schema_display_lines(md: &FileMetadata) -> Vec<(usize, String)> {
    let mut out = Vec::new();
    if md.schema.is_empty() {
        return out;
    }
    out.push((0, md.schema[0].name.clone()));
    // Walk children
    let mut stack: Vec<i32> = vec![md.schema[0].num_children.unwrap_or(0)];
    let mut depth = 1usize;
    for el in md.schema.iter().skip(1) {
        out.push((depth, el.name.clone()));
        let nc = el.num_children.unwrap_or(0);
        if nc > 0 {
            stack.push(nc);
            depth += 1;
        } else {
            // Consume one child of current top
            while let Some(top) = stack.last_mut() {
                *top -= 1;
                if *top <= 0 {
                    stack.pop();
                    if depth > 0 { depth -= 1; }
                } else {
                    break;
                }
            }
        }
    }
    out
}

fn collect_column_rows(md: &FileMetadata) -> Vec<String> {
    let mut lines = Vec::new();
    let schema_leaves = md.schema.iter().skip(1).filter(|s| s.num_children.unwrap_or(0) == 0).collect::<Vec<_>>();
    for (i, _) in schema_leaves.iter().enumerate() {
        // Gather metadata from the first row group
        let cm = md.row_groups.first()
            .and_then(|rg| rg.columns.get(i))
            .and_then(|c| c.meta_data.as_ref());
        if let Some(cm) = cm {
            let rep = repetition_name(schema_leaves[i].repetition_type.unwrap_or(1));
            let pt = physical_type_name(cm.type_);
            let cs = format_size(cm.total_compressed_size as u64);
            let us = format_size(cm.total_uncompressed_size as u64);
            let ratio = if cm.total_compressed_size > 0 {
                cm.total_uncompressed_size as f64 / cm.total_compressed_size as f64
            } else { 1.0 };
            let enc = cm.encodings.iter().map(|e| encoding_name(*e)).collect::<Vec<_>>().join(", ");
            let codec = codec_name(cm.codec);
            lines.push(format!(
                "{:<10}  {:<10}  {:<10}  {:<12}  {:.2}x  {:<28}  {:<12}",
                rep, pt, cs, us, ratio, enc, codec
            ));
        }
    }
    lines
}
